create type public.learning_situation_kind as enum ('diagnostic','launch','learning','partial_integration','global_integration','summative_assessment','remediation');
create table public.learning_situations (id uuid primary key default gen_random_uuid(), curriculum_segment_id uuid references public.curriculum_segments(id) on delete cascade, subject_id uuid references public.subjects(id), grade_level_id uuid references public.grade_levels(id), sort_order integer not null, kind public.learning_situation_kind not null, title text not null, competence text, resources jsonb not null default '[]'::jsonb, suggested_minutes integer, source_page integer, source_label text, created_at timestamptz not null default now());
alter table public.plan_items add column learning_situation_id uuid references public.learning_situations(id) on delete set null;
create table public.daily_lesson_notes (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, lesson_run_id uuid references public.lesson_runs(id) on delete cascade, plan_item_id uuid references public.plan_items(id) on delete cascade, achieved boolean, observation text, difficulties text, next_action text, homework text, created_by uuid references auth.users(id), created_at timestamptz not null default now());
alter table public.learning_situations enable row level security;alter table public.daily_lesson_notes enable row level security;
create policy "read learning situations" on public.learning_situations for select to authenticated using(true);
create policy "workspace manage daily notes" on public.daily_lesson_notes for all to authenticated using(public.is_active_member(organization_id)) with check(public.is_active_member(organization_id));
